import{_ as e,C as n,o as r,c as s,a2 as d,b as l,w as o,a as i,E as h,a3 as g}from"./chunks/framework.CAKCj7G0.js";const B=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"数据库/Mysql/Mysql.md","filePath":"数据库/Mysql/Mysql.md","lastUpdated":1767195531000}'),u={name:"数据库/Mysql/Mysql.md"};function E(S,t,b,q,A,c){const a=n("Mermaid");return r(),s("div",null,[t[1]||(t[1]=d('<h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>MySQL 是一款<strong>开源的关系型数据库管理系统（RDBMS）</strong>，由瑞典 MySQL AB 公司开发，现在隶属于 Oracle 公司。它基于 SQL（结构化查询语言）进行数据管理，核心是将数据存储在按&quot;表&quot;&quot;行&quot;&quot;列&quot;组织的关系模型中，是目前全球最流行的数据库之一，尤其在中小型应用和互联网场景中占据主导地位。</p><p>可以简单理解：如果把数据比作书籍，MySQL 就是一个&quot;智能图书馆&quot;——它负责收纳、分类、检索、修改这些&quot;书籍&quot;，并且能高效处理多个人同时查阅/修改的需求。</p><h2 id="核心特点" tabindex="-1">核心特点 <a class="header-anchor" href="#核心特点" aria-label="Permalink to &quot;核心特点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td><strong>开源免费</strong></td><td>社区版完全免费，无需支付授权费用，这是它普及的核心原因之一；企业版提供商业支持，但大部分开发者/中小企业用社区版即可满足需求。</td></tr><tr><td><strong>跨平台</strong></td><td>支持 Windows、Linux、macOS 等主流操作系统，部署灵活。</td></tr><tr><td><strong>高性能</strong></td><td>针对读写操作做了大量优化，尤其是读操作（查询）效率极高，能轻松应对高并发场景（比如电商网站的商品查询）。</td></tr><tr><td><strong>易用性</strong></td><td>语法贴近标准 SQL，学习成本低；配套工具丰富（如 Navicat、MySQL Workbench、phpMyAdmin），可视化操作降低了使用门槛。</td></tr><tr><td><strong>支持多种存储引擎</strong></td><td>最常用的是 <strong>InnoDB</strong>（支持事务、行级锁、外键，适合高并发、数据一致性要求高的场景，如电商订单）和 <strong>MyISAM</strong>（查询速度快、不支持事务，适合只读/少写场景，如日志统计）。MySQL 5.5 之后默认使用 InnoDB。</td></tr><tr><td><strong>支持事务和 ACID 特性</strong></td><td>基于 InnoDB 引擎，MySQL 支持事务（一组操作要么全成功，要么全失败），满足 ACID 原则：&lt;br&gt;• <strong>原子性</strong>（Atomicity）：事务是不可分割的最小单位&lt;br&gt;• <strong>一致性</strong>（Consistency）：事务执行前后数据状态合法&lt;br&gt;• <strong>隔离性</strong>（Isolation）：多个事务互不干扰&lt;br&gt;• <strong>持久性</strong>（Durability）：事务提交后数据永久保存</td></tr></tbody></table><h2 id="逻辑架构" tabindex="-1">逻辑架构 <a class="header-anchor" href="#逻辑架构" aria-label="Permalink to &quot;逻辑架构&quot;">​</a></h2><p>MySQL 的逻辑架构是&quot;分层设计&quot;，从客户端请求到最终返回结果，数据会依次经过这些层级处理，核心可以分为 3 层：</p>',7)),(r(),l(g,null,{default:o(()=>[h(a,{id:"mermaid-80",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5B%E5%AE%A2%E6%88%B7%E7%AB%AF%E8%AF%B7%E6%B1%82%5D%20--%3E%20B%5B%E8%BF%9E%E6%8E%A5%E5%B1%82%5D%0A%20%20%20%20B%20--%3E%20C%5B%E6%9C%8D%E5%8A%A1%E5%B1%82%5D%0A%20%20%20%20C%20--%3E%20D%5B%E5%AD%98%E5%82%A8%E5%BC%95%E6%93%8E%E5%B1%82%5D%0A%20%20%20%20D%20--%3E%20E%5B%E7%89%A9%E7%90%86%E6%95%B0%E6%8D%AE%E6%96%87%E4%BB%B6%5D%0A%20%20%20%20%0A%20%20%20%20subgraph%20%E8%BF%9E%E6%8E%A5%E5%B1%82%0A%20%20%20%20B1%5B%E8%BF%9E%E6%8E%A5%E7%AE%A1%E7%90%86%5D%0A%20%20%20%20B2%5B%E8%AE%A4%E8%AF%81%E6%8E%88%E6%9D%83%5D%0A%20%20%20%20B3%5B%E7%BA%BF%E7%A8%8B%E5%A4%84%E7%90%86%5D%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20subgraph%20%E6%9C%8D%E5%8A%A1%E5%B1%82%0A%20%20%20%20C1%5BSQL%E6%8E%A5%E5%8F%A3%5D%0A%20%20%20%20C2%5B%E6%9F%A5%E8%AF%A2%E8%A7%A3%E6%9E%90%E5%99%A8%5D%0A%20%20%20%20C3%5B%E6%9F%A5%E8%AF%A2%E4%BC%98%E5%8C%96%E5%99%A8%5D%0A%20%20%20%20C4%5B%E7%BC%93%E5%AD%98%26%E6%89%A7%E8%A1%8C%E5%99%A8%5D%0A%20%20%20%20C5%5B%E5%86%85%E7%BD%AE%E5%87%BD%E6%95%B0%2F%E5%AD%98%E5%82%A8%E8%BF%87%E7%A8%8B%5D%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20subgraph%20%E5%AD%98%E5%82%A8%E5%BC%95%E6%93%8E%E5%B1%82%0A%20%20%20%20D1%5BInnoDB%5D%0A%20%20%20%20D2%5BMyISAM%5D%0A%20%20%20%20D3%5BMemory%E7%AD%89%5D%0A%20%20%20%20end%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=d('<h3 id="连接层" tabindex="-1">连接层 <a class="header-anchor" href="#连接层" aria-label="Permalink to &quot;连接层&quot;">​</a></h3><p>连接层是最外层，负责处理客户端与 MySQL 服务器的连接，是请求的&quot;入口&quot;。</p><p><strong>核心作用</strong>：处理客户端与 MySQL 服务器的连接。</p><p><strong>关键组件</strong>：</p><ul><li>连接管理：每一个客户端连接都会创建/复用一个线程，MySQL 会限制最大连接数（<code>max_connections</code>）避免资源耗尽；</li><li>认证授权：验证用户名/密码，检查该用户是否有访问对应数据库/表的权限；</li><li>线程池：复用线程减少创建/销毁线程的开销（高并发场景关键优化）。</li></ul><h3 id="服务层" tabindex="-1">服务层 <a class="header-anchor" href="#服务层" aria-label="Permalink to &quot;服务层&quot;">​</a></h3><p>服务层是核心处理层，所有 SQL 逻辑都在这里处理，负责 SQL 的&quot;解析、优化、执行&quot;，与存储引擎无关（对下统一调用存储引擎接口）。</p><p><strong>核心组件</strong>：</p><ul><li><strong>SQL 接口</strong>：接收客户端的 SQL 语句（增删改查/存储过程等），返回执行结果；</li><li><strong>查询解析器</strong>：把 SQL 语句解析成&quot;解析树&quot;（比如把 <code>SELECT * FROM user WHERE id=1</code> 拆成&quot;查询user表、条件id=1、返回所有字段&quot;），如果 SQL 语法错误，这里会直接报错；</li><li><strong>查询优化器</strong>：对解析树做&quot;最优执行计划&quot;选择（比如先过滤条件还是先联表、用哪个索引），比如同样的查询，优化器会选&quot;走主键索引&quot;而非&quot;全表扫描&quot;，保证执行效率；</li><li><strong>缓存</strong>（MySQL 8.0 已移除）：MySQL 5.7 及之前有 Query Cache，缓存常用查询的结果，相同查询直接返回缓存（但实际中缓存失效快，8.0 直接删掉了）；</li><li><strong>执行器</strong>：根据优化后的执行计划，调用存储引擎的接口（比如 InnoDB 的&quot;读取行&quot;接口），获取数据并返回。</li></ul><h3 id="存储引擎层" tabindex="-1">存储引擎层 <a class="header-anchor" href="#存储引擎层" aria-label="Permalink to &quot;存储引擎层&quot;">​</a></h3><p>存储引擎层是数据存储/读取的核心，是 MySQL 最具特色的一层——<strong>插件式设计</strong>，不同存储引擎负责不同的物理数据存储方式，上层服务层只需要调用统一的接口（如 <code>read_row</code>、<code>write_row</code>），无需关心底层实现。</p><p><strong>核心职责</strong>：数据的存储、读取、锁管理、事务处理等。</p><p><strong>常用引擎</strong>：</p><ul><li>InnoDB：默认引擎，支持事务、行级锁、外键，数据存在 <code>ibd</code> 文件中；</li><li>MyISAM：不支持事务，表级锁，数据存在 <code>MYD</code>（数据）+ <code>MYI</code>（索引）文件中；</li><li>Memory：内存引擎，数据存在内存中，速度极快但重启丢失。</li></ul><h2 id="物理架构" tabindex="-1">物理架构 <a class="header-anchor" href="#物理架构" aria-label="Permalink to &quot;物理架构&quot;">​</a></h2><p>物理架构指 MySQL 的数据、日志、配置等文件在磁盘上的存储结构，不同操作系统存储路径不同（Linux 一般在 <code>/var/lib/mysql</code>），核心文件类型：</p><table tabindex="0"><thead><tr><th>文件类型</th><th>作用</th></tr></thead><tbody><tr><td>数据库目录（如 test_db）</td><td>每个数据库对应一个目录，存储该库下所有表的文件</td></tr><tr><td>.frm 文件</td><td>表结构文件（存储表的字段、索引定义等），所有引擎都有</td></tr><tr><td>.ibd 文件（InnoDB）</td><td>存储 InnoDB 表的数据和索引（如果是独立表空间模式，默认开启）</td></tr><tr><td>.MYD/.MYI 文件（MyISAM）</td><td>.MYD 存数据，.MYI 存索引</td></tr><tr><td>binlog</td><td>二进制日志，记录所有数据修改操作（用于备份、主从复制）</td></tr><tr><td>redo log</td><td>重做日志（InnoDB 特有），保证事务持久性（崩溃后恢复数据）</td></tr><tr><td>undo log</td><td>回滚日志（InnoDB 特有），保证事务原子性（执行失败时回滚数据）</td></tr><tr><td>my.cnf / my.ini</td><td>配置文件（Linux/Windows），定义 MySQL 的核心参数（端口、内存、字符集）</td></tr></tbody></table><h2 id="部署架构" tabindex="-1">部署架构 <a class="header-anchor" href="#部署架构" aria-label="Permalink to &quot;部署架构&quot;">​</a></h2><p>实际生产中不会只用&quot;单机 MySQL&quot;，而是根据业务规模选择不同部署架构。</p><h3 id="单机架构" tabindex="-1">单机架构 <a class="header-anchor" href="#单机架构" aria-label="Permalink to &quot;单机架构&quot;">​</a></h3><p>最简单的架构：一台服务器运行 MySQL 实例，数据存在本地磁盘。</p><ul><li>优点：部署简单、成本低；</li><li>缺点：单点故障（服务器挂了，业务就无法访问），性能上限低。</li></ul><h3 id="主从架构" tabindex="-1">主从架构 <a class="header-anchor" href="#主从架构" aria-label="Permalink to &quot;主从架构&quot;">​</a></h3><p>最常用架构，读写分离。</p><p><strong>核心设计</strong>：1 个主库（Master）+ 1/N 个从库（Slave）；</p><ul><li>主库：负责<strong>写操作</strong>（增删改），并把修改记录到 binlog；</li><li>从库：通过复制主库的 binlog 同步数据，只负责<strong>读操作</strong>（查询）；</li></ul><p><strong>优点</strong>：</p><ul><li>读写分离：缓解单机读写压力（比如电商场景，查询远多于修改）；</li><li>容灾：主库挂了，可把从库提升为主库；</li></ul><p><strong>关键</strong>：主从复制是<strong>异步/半同步</strong>的，可能存在短暂的数据延迟。</p><h3 id="主主架构" tabindex="-1">主主架构 <a class="header-anchor" href="#主主架构" aria-label="Permalink to &quot;主主架构&quot;">​</a></h3><p><strong>核心设计</strong>：两台服务器互为主库和从库，都能处理读写操作；</p><ul><li>适用场景：需要高可用（主库故障时，另一台可立即接管），且写操作压力较大的场景；</li><li>注意：需避免&quot;写冲突&quot;（比如两台同时修改同一行数据）。</li></ul><h3 id="集群架构" tabindex="-1">集群架构 <a class="header-anchor" href="#集群架构" aria-label="Permalink to &quot;集群架构&quot;">​</a></h3><p>当单库数据量达到 TB 级、QPS 达到 10 万+时，主从架构也扛不住，需要分库分表：</p><ul><li>分库：把一个大数据库拆成多个小数据库（比如按业务拆：订单库、用户库）；</li><li>分表：把一个大表拆成多个小表（比如用户表按 id 拆：user_1、user_2）；</li></ul><p><strong>常用方案</strong>：基于 Sharding-JDBC、MyCat 等中间件实现，或用 MySQL Cluster（官方集群方案）。</p><h2 id="数据库核心分类" tabindex="-1">数据库核心分类 <a class="header-anchor" href="#数据库核心分类" aria-label="Permalink to &quot;数据库核心分类&quot;">​</a></h2><p>首先要分清数据库的核心类型，这是对比的基础：</p><table tabindex="0"><thead><tr><th>类型</th><th>代表数据库</th><th>核心特点</th></tr></thead><tbody><tr><td>关系型数据库（RDBMS）</td><td>MySQL、PostgreSQL、Oracle、SQL Server</td><td>基于表/行/列，支持SQL、事务、ACID</td></tr><tr><td>非关系型数据库（NoSQL）</td><td>MongoDB、Redis</td><td>无固定表结构，分文档/键值/列族等类型</td></tr></tbody></table><h2 id="vs-postgresql" tabindex="-1">vs PostgreSQL <a class="header-anchor" href="#vs-postgresql" aria-label="Permalink to &quot;vs PostgreSQL&quot;">​</a></h2><p>两者都是开源免费的关系型数据库，常被拿来对比，核心差异在&quot;定位和特性广度&quot;：</p><table tabindex="0"><thead><tr><th>维度</th><th>MySQL</th><th>PostgreSQL</th></tr></thead><tbody><tr><td><strong>核心定位</strong></td><td>轻量、高性能，主打&quot;易用+高效&quot;</td><td>功能全面、标准兼容，主打&quot;强大+严谨&quot;</td></tr><tr><td><strong>SQL 兼容性</strong></td><td>部分兼容标准 SQL，有自定义扩展</td><td>几乎完全兼容标准 SQL，规范度更高</td></tr><tr><td><strong>高级特性</strong></td><td>基础功能满足大部分场景，高级特性（如复杂查询、自定义函数）较弱</td><td>支持复杂查询、自定义函数/存储过程、地理信息（GIS）、JSON 处理、全文检索等，功能更全面</td></tr><tr><td><strong>性能</strong></td><td>读操作性能极佳，写操作（高并发）稍弱（InnoDB 已优化）</td><td>复杂查询（多表联查、聚合）性能更强，简单读写略逊于 MySQL</td></tr><tr><td><strong>适用场景</strong></td><td>互联网应用（电商、社交、博客）、中小型系统、读多写少场景</td><td>企业级复杂业务（金融、数据分析）、需要复杂查询/地理信息的场景</td></tr><tr><td><strong>生态</strong></td><td>第三方工具多，社区活跃，教程丰富</td><td>生态稍小，但专业领域（GIS、数据分析）生态更优</td></tr></tbody></table><p><strong>一句话总结</strong>：MySQL 胜在&quot;轻量、易用、读性能&quot;，PostgreSQL 胜在&quot;功能全面、标准兼容、复杂场景&quot;。</p><h2 id="vs-oracle" tabindex="-1">vs Oracle <a class="header-anchor" href="#vs-oracle" aria-label="Permalink to &quot;vs Oracle&quot;">​</a></h2><p>Oracle 是闭源商业数据库的代表，和 MySQL 同属 Oracle 公司，但定位完全不同：</p><table tabindex="0"><thead><tr><th>维度</th><th>MySQL</th><th>Oracle</th></tr></thead><tbody><tr><td><strong>成本</strong></td><td>社区版免费，企业版低成本</td><td>收费昂贵（按CPU/用户授权），仅大型企业能承担</td></tr><tr><td><strong>性能&amp;扩展性</strong></td><td>单机性能优秀，集群需依赖第三方（如主从、分库分表）</td><td>原生支持高可用集群（RAC）、分布式，支持PB级数据，性能无上限</td></tr><tr><td><strong>特性</strong></td><td>满足80%的通用场景，高级特性（如高级安全、分布式事务）缺失</td><td>全栈特性：高级安全、分布式事务、数据仓库、灾备、审计等，企业级特性最全</td></tr><tr><td><strong>适用场景</strong></td><td>中小型应用、互联网创业公司、非核心业务</td><td>大型企业核心业务（金融、银行、电信）、对稳定性/安全性要求极高的场景</td></tr><tr><td><strong>维护成本</strong></td><td>维护简单，新手易上手</td><td>维护复杂，需专业DBA团队</td></tr></tbody></table><p><strong>一句话总结</strong>：MySQL 是&quot;性价比之王&quot;，适合中小规模；Oracle 是&quot;企业级旗舰&quot;，适合核心业务但成本极高。</p><h2 id="vs-sql-server" tabindex="-1">vs SQL Server <a class="header-anchor" href="#vs-sql-server" aria-label="Permalink to &quot;vs SQL Server&quot;">​</a></h2><p>SQL Server 是微软的闭源商业数据库，和 Windows 生态深度绑定：</p><table tabindex="0"><thead><tr><th>维度</th><th>MySQL</th><th>SQL Server</th></tr></thead><tbody><tr><td><strong>跨平台</strong></td><td>支持Windows/Linux/macOS</td><td>主要支持Windows，Linux版本功能有限</td></tr><tr><td><strong>生态整合</strong></td><td>无专属生态，适配所有开发语言</td><td>与.NET、Visual Studio、Office深度整合，微软技术栈首选</td></tr><tr><td><strong>成本</strong></td><td>社区版免费</td><td>收费（比Oracle低），有开发版免费</td></tr><tr><td><strong>易用性</strong></td><td>命令行/第三方工具为主</td><td>可视化工具（SSMS）极其完善，新手友好</td></tr><tr><td><strong>适用场景</strong></td><td>跨平台应用、非微软技术栈</td><td>微软技术栈（.NET）、Windows服务器环境、中小型企业</td></tr></tbody></table><p><strong>一句话总结</strong>：选 MySQL 还是 SQL Server，核心看技术栈——非微软栈选 MySQL，.NET/Windows 栈选 SQL Server。</p><h2 id="vs-mongodb" tabindex="-1">vs MongoDB <a class="header-anchor" href="#vs-mongodb" aria-label="Permalink to &quot;vs MongoDB&quot;">​</a></h2><p>这是关系型 vs 非关系型的核心对比，底层设计理念完全不同：</p><table tabindex="0"><thead><tr><th>维度</th><th>MySQL（关系型）</th><th>MongoDB（文档型NoSQL）</th></tr></thead><tbody><tr><td><strong>数据模型</strong></td><td>固定表结构（需先建表），强类型</td><td>无固定结构（JSON文档），灵活扩展</td></tr><tr><td><strong>事务支持</strong></td><td>支持ACID（InnoDB），事务成熟</td><td>4.0+支持事务，但性能/稳定性弱于MySQL</td></tr><tr><td><strong>查询能力</strong></td><td>支持复杂SQL查询（联表、聚合）</td><td>简单查询快，复杂联表查询弱</td></tr><tr><td><strong>扩展性</strong></td><td>水平扩展需分库分表（复杂）</td><td>原生支持分布式（分片），水平扩展简单</td></tr><tr><td><strong>适用场景</strong></td><td>数据结构固定、需事务、复杂查询（订单、用户、财务）</td><td>数据结构多变（电商商品、社交动态）、高并发写入（日志、物联网）、快速迭代的业务</td></tr></tbody></table><p><strong>一句话总结</strong>：数据结构固定、需事务选 MySQL；数据结构灵活、需快速扩展选 MongoDB。</p><h2 id="数据库选型决策表" tabindex="-1">数据库选型决策表 <a class="header-anchor" href="#数据库选型决策表" aria-label="Permalink to &quot;数据库选型决策表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>业务场景</th><th>首选数据库</th><th>核心原因</th></tr></thead><tbody><tr><td>互联网创业公司、读多写少的Web应用</td><td>MySQL</td><td>免费、高性能、易维护</td></tr><tr><td>复杂数据分析、地理信息、科研业务</td><td>PostgreSQL</td><td>功能全面、SQL标准、复杂查询强</td></tr><tr><td>银行/金融核心系统、超大规模企业业务</td><td>Oracle</td><td>稳定性、安全性、集群能力顶级</td></tr><tr><td>.NET开发、Windows服务器环境</td><td>SQL Server</td><td>生态深度整合</td></tr><tr><td>商品/内容存储、物联网日志、快速迭代业务</td><td>MongoDB</td><td>结构灵活、水平扩展简单</td></tr></tbody></table>',57))])}const y=e(u,[["render",E]]);export{B as __pageData,y as default};
